 * The two policy kinds a route can enforce: token buckets and sliding
 * windows. Each keeps one independent state per key, created lazily the
 * first time that key reaches the policy.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: this.capacity * this.per, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      const capNumerator = this.capacity * this.per
      state.numerator += this.refill * elapsed
      if (state.numerator > capNumerator) state.numerator = capNumerator
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.#state(key).numerator >= this.per
  }

  record(key) {
    this.#state(key).numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    while (state.ticks.length > 0 && state.ticks[0] <= threshold) state.ticks.shift()
  }

  allows(key) {
    return BigInt(this.#state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.#state(key).ticks.push(tick)
  }
}
