{"file_path":"./src/engine.js","content":"/**
 * Parses a limiter file and, in the same pass, replays its events. Parsing
 * and replay are combined because a tick regression is only detectable
 * while walking the events in order, and the specification treats it as
 * just another parse-time failure: the whole file is validated, or nothing
 * is printed at all.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INTEGER_RE = /^(0|[1-9][0-9]*)$/

/** Thrown for any malformed or semantically invalid line. */
export class LineError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

function checkName(line, value, reason) {
  if (!NAME_RE.test(value)) throw new LineError(line, `${reason} ${value}`)
}

function checkInteger(line, field, value, least) {
  if (!INTEGER_RE.test(value) || BigInt(value) < least) {
    throw new LineError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(value)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Finds the route whose prefix matches the key and is longest among those
 * that match. Route prefixes are unique, so at most one route can be
 * longest.
 */
function matchRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Runs the whole simulation described by `text`. Returns `{ events, keys }`
 * on success: `events` is the per-event verdict list in log order, and
 * `keys` is a Map from key to `{ allowed, denied }` totals in first-seen
 * order. Throws a `LineError` at the first invalid line.
 */
export function run(text) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  const keys = new Map()
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new LineError(lineNumber, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LineError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(lineNumber, name, 'invalid policy name')
      const capacity = checkInteger(lineNumber, 'capacity', capacityStr, 1n)
      const refill = checkInteger(lineNumber, 'refill', refillStr, 0n)
      const per = checkInteger(lineNumber, 'per', perStr, 1n)
      if (policies.has(name)) throw new LineError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LineError(lineNumber, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = tokens
      checkName(lineNumber, name, 'invalid policy name')
      const limit = checkInteger(lineNumber, 'limit', limitStr, 0n)
      const span = checkInteger(lineNumber, 'span', spanStr, 1n)
      if (policies.has(name)) throw new LineError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LineError(lineNumber, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(lineNumber, prefix, 'invalid route prefix')
      if (routesByPrefix.has(prefix)) throw new LineError(lineNumber, `prefix ${prefix} is routed twice`)
      const routePolicies = []
      for (const name of policyNames) {
        const policy = policies.get(name)
        if (policy === undefined) throw new LineError(lineNumber, `unknown policy ${name}`)
        routePolicies.push(policy)
      }
      const route = { prefix, policies: routePolicies }
      routes.push(route)
      routesByPrefix.set(prefix, route)
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LineError(lineNumber, 'expected event <tick> <key>')
      }
      const [, tickStr, key] = tokens
      const tick = checkInteger(lineNumber, 'tick', tickStr, 0n)
      checkName(lineNumber, key, 'invalid key')
      if (lastTick !== null && tick < lastTick) {
        throw new LineError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      seenEvent = true
      lastTick = tick

      const route = matchRoute(routes, key)
      const routePolicies = route === null ? [] : route.policies

      for (const policy of routePolicies) policy.advance(key, tick)

      let denyPolicy = null
      for (const policy of routePolicies) {
        if (!policy.allows(key)) {
          denyPolicy = policy
          break
        }
      }

      let totals = keys.get(key)
      if (totals === undefined) {
        totals = { allowed: 0, denied: 0 }
        keys.set(key, totals)
      }

      if (denyPolicy === null) {
        for (const policy of routePolicies) policy.record(key, tick)
        totals.allowed += 1
        events.push({ tick, key, allow: true })
      } else {
        totals.denied += 1
        events.push({ tick, key, allow: false, policy: denyPolicy.name })
      }
    } else {
      throw new LineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { events, keys }
}
"}

