/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { run, LineError } from './engine.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
  fail('usage: cli.js replay|summary')
}

const input = readFileSync(0, 'utf8')

let result
try {
  result = run(input)
} catch (error) {
  if (error instanceof LineError) {
    fail(`line ${error.line}: ${error.message}`)
  }
  throw error
}

const lines = []
if (mode === 'replay') {
  for (const event of result.events) {
    if (event.allow) {
      lines.push(`${event.tick} ${event.key} allow`)
    } else {
      lines.push(`${event.tick} ${event.key} deny ${event.policy}`)
    }
  }
} else {
  let totalAllowed = 0
  let totalDenied = 0
  const sortedKeys = [...result.keys.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  for (const key of sortedKeys) {
    const totals = result.keys.get(key)
    totalAllowed += totals.allowed
    totalDenied += totals.denied
    lines.push(`${key} allowed=${totals.allowed} denied=${totals.denied}`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
}

process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
process.exit(0)
"}

